import {
  boolean,
  integer,
  pgTable,
  numeric,
  text,
  timestamp,
  bigint,
  jsonb,
} from "drizzle-orm/pg-core";

// Removed enum to stay robust against db synchronization issues
// export const userPlans = pgEnum("user_plan", ["free", "pro", "ai_plus"]);

export const users = pgTable("users", {
  id: text("id").primaryKey(),
  email: text("email").unique(),
  name: text("name"),
  passwordHash: text("password_hash"),
  salt: text("salt"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  plan: text("plan").default("free").notNull(),
  subscriptionStatus: text("subscription_status").default("active"), // active, past_due, canceled
  usageCount: integer("usage_count").default(0),
  webSearchCount: integer("web_search_count").default(0), // Daily web search limit tracking
  lastReset: timestamp("last_reset", { withTimezone: true }),
});

export const googleFitTokens = pgTable("google_fit_tokens", {
  userId: text("user_id")
    .primaryKey()
    .references(() => users.id, { onDelete: "cascade" }),
  accessToken: text("access_token").notNull(),
  refreshToken: text("refresh_token").notNull(),
  expiryDate: bigint("expiry_date", { mode: "number" }),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
});

export const goals = pgTable("goals", {
  userId: text("user_id")
    .primaryKey()
    .references(() => users.id, { onDelete: "cascade" }),
  waterGoalMl: integer("water_goal_ml").notNull().default(2500),
  calorieGoal: integer("calorie_goal").notNull().default(2200),
  activityGoalMin: integer("activity_goal_min").notNull().default(30),
  mealGoalCount: integer("meal_goal_count").notNull().default(3),
  weightGoalKg: integer("weight_goal_kg").notNull().default(0),
  proteinGoalG: integer("protein_goal_g").notNull().default(0),
  carbsGoalG: integer("carbs_goal_g").notNull().default(0),
  fatGoalG: integer("fat_goal_g").notNull().default(0),
  sleepGoalHours: integer("sleep_goal_hours").notNull().default(8),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
});

export const entries = pgTable("entries", {
  id: text("id").primaryKey(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  type: text("type").notNull(),
  name: text("name"),
  calories: integer("calories"),
  mealType: text("meal_type"),
  amountMl: integer("amount_ml"),
  activityType: text("activity_type"),
  durationMin: integer("duration_min"),
  estimatedCalories: integer("estimated_calories"),
  amountG: integer("amount_g"),
  proteinG: integer("protein_g"),
  carbsG: integer("carbs_g"),
  fatG: integer("fat_g"),
  timestamp: timestamp("timestamp", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
});

export const foodLibrary = pgTable("food_library", {
  id: text("id").primaryKey(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  caloriesPer100: integer("calories_per_100"),
  proteinPer100: integer("protein_per_100"),
  carbsPer100: integer("carbs_per_100"),
  fatPer100: integer("fat_per_100"),
  barcode: text("barcode"),
  imageUrl: text("image_url"),
  source: text("source").notNull().default("manual"),
  favorite: boolean("favorite").notNull().default(false),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
});

export const profiles = pgTable("profiles", {
  userId: text("user_id")
    .primaryKey()
    .references(() => users.id, { onDelete: "cascade" }),
  fullName: text("full_name"),
  age: integer("age"),
  heightCm: integer("height_cm"),
  weightKg: integer("weight_kg"),
  mainGoal: text("main_goal"),
  sportLevel: text("sport_level"),
  workoutDays: text("workout_days"),
  workoutPlace: text("workout_place"),
  equipmentLevel: text("equipment_level"),
  injury: text("injury"),
  injuryDetail: text("injury_detail"),
  doctorRestriction: text("doctor_restriction"),
  referralSource: text("referral_source"),
  expectation: text("expectation"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
});

export const userSettings = pgTable("user_settings", {
  userId: text("user_id")
    .primaryKey()
    .references(() => users.id, { onDelete: "cascade" }),
  themeMode: text("theme_mode").notNull().default("light"),
  themeAccent: text("theme_accent").notNull().default("amber"),
  reminderEnabled: boolean("reminder_enabled").notNull().default(false),
  reminderTime: text("reminder_time").notNull().default("20:00"),
  reminderLastNotifiedDay: text("reminder_last_notified_day"),
  aiVisual: boolean("ai_visual").notNull().default(false),
  googleFit: boolean("google_fit").notNull().default(false),
  darkMode: boolean("dark_mode").notNull().default(true),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
});

export const auditLog = pgTable("audit_log", {
  id: text("id").primaryKey(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  action: text("action").notNull(),
  detail: text("detail").notNull(),
  meta: jsonb("meta"),
  timestamp: timestamp("timestamp", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
});

export const measurements = pgTable("measurements", {
  id: text("id").primaryKey(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  type: text("type").notNull(),
  value: numeric("value", { precision: 6, scale: 2, mode: "number" }).notNull(),
  unit: text("unit").notNull(),
  timestamp: timestamp("timestamp", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
});

export const reportShares = pgTable("report_shares", {
  id: text("id").primaryKey(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  rangeDays: integer("range_days").notNull().default(30),
  expiresAt: timestamp("expires_at", { withTimezone: true }),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
});

export const integrations = pgTable("integrations", {
  id: text("id").primaryKey(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  provider: text("provider").notNull(),
  status: text("status").notNull().default("disconnected"),
  accessToken: text("access_token"),
  refreshToken: text("refresh_token"),
  expiryDate: bigint("expiry_date", { mode: "number" }),
  scopes: text("scopes"),
  meta: jsonb("meta"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
});

export const sleepLogs = pgTable("sleep_logs", {
  id: text("id").primaryKey(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  sleepStart: timestamp("sleep_start", { withTimezone: true }).notNull(),
  sleepEnd: timestamp("sleep_end", { withTimezone: true }).notNull(),
  durationMin: integer("duration_min").notNull(),
  quality: text("quality").notNull().default("good"), // poor, fair, good, excellent
  note: text("note"),
  timestamp: timestamp("timestamp", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
});
